# Code generated by Claude
"""
Measurement only: (e) the hand turn of the move PLACE: OVER and (f) the beaker's slide and tilt in the grip, from experiments/carry_boundary_replay.py's carry.npz.

    python experiments/carry_boundary_report.py carry.npz [--b 80.4947 --o 80.508 --d 82.661 --u0 77.588]

b = first tick after UP, o = start of PLACE: OVER, d = start of PLACE: DOWN, u0 = start of UP (sim seconds, from phases.json). Slide = the beaker's bottom centre in the pad frame
minus its value at b - 0.05 s; tilt = the angle between the beaker's axis and the world vertical; tilt in the hand = the angle between the beaker's axis in the pad frame now and at b - 0.05 s.
"""
import argparse

import numpy as np
from scipy.spatial.transform import Rotation as Rot


def main(a):
    z = np.load(a.npz)
    t = z["t"]
    bp, bR, pp, pR = z["bp"], z["bR"].reshape(-1, 3, 3), z["pp"], z["pR"].reshape(-1, 3, 3)
    i0 = int(np.searchsorted(t, a.b - 0.05))
    rel = np.einsum("nji,nj->ni", pR, bp - pp)                              # beaker bottom centre in the pad frame
    ax = np.einsum("nji,nj->ni", pR, bR[:, :, 2])                            # beaker axis (its z) in the pad frame
    slide = rel - rel[i0]
    tilt_world = np.degrees(np.arccos(np.clip(bR[:, 2, 2], -1, 1)))
    tilt_hand = np.degrees(np.arccos(np.clip(ax @ ax[i0], -1, 1)))
    print(f"samples {len(t)}  t {t[0]:.3f}..{t[-1]:.3f}  reference sample t={t[i0]:.3f}")
    print(f"beaker in the pad frame at the reference (m): {np.round(rel[i0], 4)}   axis in pad frame {np.round(ax[i0], 4)}")

    def win(name, lo, hi):
        m = (t >= lo) & (t < hi)
        if not m.any():
            return
        s = np.linalg.norm(slide[m], axis=1)
        print(f"  {name:34s} slide max {1000*s.max():6.2f} mm (comp max {np.round(1000*np.abs(slide[m]).max(axis=0),2)})  tilt in hand max {tilt_hand[m].max():5.2f} deg  tilt world {tilt_world[m].min():5.2f}..{tilt_world[m].max():5.2f} deg")

    print("\n(f) slide and tilt of the beaker in the grip")
    win("UP middle half", a.u0 + 0.25 * (a.b - a.u0), a.b - 0.25 * (a.b - a.u0))
    win("last 0.5 s of UP", a.b - 0.5, a.b)
    for k in range(0, 9):
        win(f"PLACE OVER {0.25*k:.2f}..{0.25*(k+1):.2f} s", a.o + 0.25 * k, a.o + 0.25 * (k + 1))
    win("PLACE OVER whole", a.o, a.d)
    win("DOWN first 0.5 s", a.d, a.d + 0.5)
    # rates: slide speed (mm/s) at the 750 Hz steps smoothed over 5 steps, peak in windows
    sp = np.linalg.norm(np.diff(rel, axis=0), axis=1) / np.diff(t)
    sp = np.convolve(sp, np.ones(5) / 5, mode="same")
    for name, lo, hi in (("UP middle half", a.u0 + 0.25 * (a.b - a.u0), a.b - 0.25 * (a.b - a.u0)), ("PLACE OVER first 0.5 s", a.o, a.o + 0.5), ("PLACE OVER whole", a.o, a.d)):
        m = (t[1:] >= lo) & (t[1:] < hi)
        print(f"  beaker speed in the grip, {name}: peak {1000*sp[m].max():.1f} mm/s")

    print("\n(e) the hand turn of PLACE: OVER (pad frame)")
    ia, ib = int(np.searchsorted(t, a.o)), int(np.searchsorted(t, a.d))
    Ra, Rb = pR[ia], pR[ib]
    rv = Rot.from_matrix(Ra.T @ Rb).as_rotvec()
    ang = float(np.linalg.norm(rv))
    yaw = lambda R: np.degrees(np.arctan2(R[1, 0], R[0, 0]))
    dist = float(np.linalg.norm(pp[ib] - pp[ia]))
    print(f"  at OVER start: pad {np.round(pp[ia],4)}, at OVER end (DOWN start): pad {np.round(pp[ib],4)}")
    print(f"  pad travel {1000*dist:.1f} mm; total rotation {np.degrees(ang):.1f} deg ({ang:.3f} rad); of it about the vertical: {np.degrees(np.arctan2(*(Rb @ Ra.T)[[1, 0], 0])):.1f} deg (pad x axis yaw {yaw(Ra):.1f} -> {yaw(Rb):.1f})")
    print(f"  planned time terms: distance/speed = {dist:.3f}/0.12 = {dist/0.12:.2f} s; turn = {ang:.3f}/0.5 = {ang/0.5:.2f} s; min_move_s 1.0; joint arc 2.0*0.29/0.5 = 1.16 s; planned 1.7 s")
    # angular speed of the pad frame (rad/s) over 0.1 s differences
    st = 75
    w = []
    tt = []
    for k in range(ia, ib - st, st):
        w.append(np.linalg.norm(Rot.from_matrix(pR[k].T @ pR[k + st]).as_rotvec()) / (t[k + st] - t[k]))
        tt.append(t[k])
    w = np.array(w)
    print(f"  pad angular speed (0.1 s differences): peak {w.max():.3f} rad/s at t={tt[int(np.argmax(w))]:.2f}, mean over the move {ang/(a.d-a.o):.3f} rad/s")
    v = []
    for k in range(ia, ib - st, st):
        v.append(np.linalg.norm(pp[k + st] - pp[k]) / (t[k + st] - t[k]))
    print(f"  pad speed (0.1 s differences): peak {max(v):.3f} m/s, mean over the move {dist/(a.d-a.o):.3f} m/s")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("npz")
    ap.add_argument("--b", type=float, default=80.4947)
    ap.add_argument("--o", type=float, default=80.508)
    ap.add_argument("--d", type=float, default=82.661)
    ap.add_argument("--u0", type=float, default=77.588)
    main(ap.parse_args())
